export type ParsedEnrollCreatorInstruction<
  TProgram extends string = typeof KOLAB_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    creator: TAccountMetas[0];
    payer: TAccountMetas[1];
    config: TAccountMetas[2];
    campaign: TAccountMetas[3];
    /** The brand's approval for this creator, or the campaign's open invite. */
    approval: TAccountMetas[4];
    enrollment: TAccountMetas[5];
    systemProgram: TAccountMetas[6];
  };
  data: EnrollCreatorInstructionData;
};

export function parseEnrollCreatorInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedEnrollCreatorInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 7,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      creator: getNextAccount(),
      payer: getNextAccount(),
      config: getNextAccount(),
      campaign: getNextAccount(),
      approval: getNextAccount(),
      enrollment: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getEnrollCreatorInstructionDataDecoder().decode(instruction.data),
  };
}
